  ["inbox-counts", "\"$HORIZON_BIN\" inbox list --json | jq '{top_keys:(keys), count:(.items|length), by_kind:(.items|group_by(.kind)|map({kind:.[0].kind,count:length})), by_status:(.items|group_by(.status)|map({status:.[0].status,count:length})), open_items:[.items[]|select(.status==\"open\")|{id,kind,title,owner,to,read}]}'"],
  ["status-summary", "\"$HORIZON_BIN\" status --json | jq '.'"],
  ["usage-summary", "\"$HORIZON_BIN\" usage --json | jq '.'"],
  ["git-status", "\"$HORIZON_GIT\" status --short --untracked-files=all"],
  ["git-log", "\"$HORIZON_GIT\" log --oneline --decorate -30 -- 'MainProjects/Algebraic-Jacobian-Challenge-Rebuild'"],
  ["run-dirs", "find \"$ARCHON_HORIZON_ROOT/.archon-horizon\" -maxdepth 3 -type f \\( -name report -o -name report.md -o -name '*.json' \\) -print | sort | tail -80"]
];
const rs = await Promise.all(cmds.map(async ([name,cmd]) => {
  const r=await tools.exec_command({cmd,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:10000,max_output_tokens:10000});
  return `---${name}---\n${r.output}`;
}));
rs.forEach(text);

const paths = [
  "/home/axel/LeanAlgebraicGeometry-Horizon/.claude/skills/horizon-inbox/SKILL.md",
  "/home/axel/LeanAlgebraicGeometry-Horizon/.claude/skills/project-git/SKILL.md",
  "/home/axel/LeanAlgebraicGeometry-Horizon/.claude/skills/hgraph/SKILL.md",
  "/home/axel/LeanAlgebraicGeometry-Horizon/.claude/skills/task-status/SKILL.md"
