  ["scoped-classification", "git_status=$(\"$HORIZON_GIT\" status --porcelain=v1 --untracked-files=all); printf '%s\\n' \"$git_status\" | awk 'BEGIN{n=0;tracked=0;untracked=0;hgraph=0;nonhgraph=0;lean=0;tex=0;yaml=0;json=0;md=0;other=0} {x=substr($0,1,2);p=substr($0,4); if(p !~ /^MainProjects\\/(Algebraic-Jacobian-Challenge-Rebuild|Algebraic-Jacobian-Challenge)\\//)next;n++; if(x==\"??\")untracked++; else tracked++; if(p ~ /\\/hgraph\\//)hgraph++; else {nonhgraph++; if(p ~ /\\.lean$/)lean++; else if(p ~ /\\.tex$/)tex++; else if(p ~ /\\.ya?ml$/)yaml++; else if(p ~ /\\.json$/)json++; else if(p ~ /\\.md$/)md++; else other++}} END{printf \"scoped total=%d tracked=%d untracked=%d hgraph=%d nonhgraph=%d lean=%d tex=%d yaml=%d json=%d md=%d other=%d\\n\",n,tracked,untracked,hgraph,nonhgraph,lean,tex,yaml,json,md,other}'"],
